#define sballoc(sb, m) { \
    (sb)->sb_cc += (m)->m_len; \
    (sb)->sb_mbcnt += MSIZE; \
    if ((m)->m_flags & M_EXT) \
        (sb)->sb_mbcnt += (m)->m_ext.ext_size; \
}
#define sbfree(sb, m) { \
    (sb)->sb_cc -= (m)->m_len; \
    (sb)->sb_mbcnt -= MSIZE; \
    if ((m)->m_flags & M_EXT) \
        (sb)->sb_mbcnt -= (m)->m_ext.ext_size; \
}

