    u8 rn_flags;                    /* 0x0B */
    union {
        struct {
            char *rn_Key;           /* 0x0C */
            char *rn_Mask;          /* 0x10 */
            struct radix_node *rn_Dupedkey; /* 0x14 */
        } rn_leaf;
        struct {
            s32 rn_Off;             /* 0x0C */
            struct radix_node *rn_L; /* 0x10 */
            struct radix_node *rn_R; /* 0x14 */
        } rn_node;
    } rn_u;
};
