/* SCE: per-thread select/poll waiter (socket->so_waiter) */
struct SceNetInetWaiter {
    u8 unk0[0x20];
    s32 unk20;                  /* 0x20 waiting */
    u8 unk24[0x48 - 0x24];
    s32 flags;                  /* 0x48 */
    SceUID sema;                /* 0x4C */
#if FW_VERSION < 150
    u8 unk50[4];
#endif
    struct socket *sockets;     /* 0x54 (1.00) / 0x50 (1.50+): list linked by so_selnext */
};



