    void (*Open)(struct sppp *sp);  /* 0x10 */
    void (*Close)(struct sppp *sp); /* 0x14 */
    void (*TO)(void *sp);           /* 0x18 */
    s32 (*RCR)();                   /* 0x1C */
    void (*RCN_rej)();              /* 0x20 */
    void (*RCN_nak)();              /* 0x24 */
    void (*tlu)(struct sppp *sp);   /* 0x28 */
    void (*tld)(struct sppp *sp);   /* 0x2C */
    void (*tls)(struct sppp *sp);   /* 0x30 */
    void (*tlf)(struct sppp *sp);   /* 0x34 */
